import React, { useMemo, useState } from 'react';
import {
  Chip,
  ChipGroup,
  CircularProgress,
  Badge,
  Pagination,
  EmptyState,
  Button,
  Stack,
  Card,
  Text,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over_quota' | 'completed';

interface Project {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Атлас', quotaPercent: 42, status: 'active' },
  { id: 'p2', name: 'Меркурий', quotaPercent: 87, status: 'active' },
  { id: 'p3', name: 'Орион', quotaPercent: 100, status: 'over_quota' },
  { id: 'p4', name: 'Веста', quotaPercent: 15, status: 'paused' },
  { id: 'p5', name: 'Гелиос', quotaPercent: 68, status: 'active' },
  { id: 'p6', name: 'Феникс', quotaPercent: 100, status: 'completed' },
  { id: 'p7', name: 'Кассиопея', quotaPercent: 33, status: 'paused' },
  { id: 'p8', name: 'Тритон', quotaPercent: 95, status: 'over_quota' },
  { id: 'p9', name: 'Циклон', quotaPercent: 50, status: 'active' },
  { id: 'p10', name: 'Немезида', quotaPercent: 100, status: 'completed' },
  { id: 'p11', name: 'Ирида', quotaPercent: 22, status: 'paused' },
  { id: 'p12', name: 'Аврора', quotaPercent: 76, status: 'active' },
];

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' | 'neutral' }> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'neutral' },
  over_quota: { label: 'Превышена квота', tone: 'danger' },
  completed: { label: 'Завершён', tone: 'warning' },
};

const ALL_STATUSES = Object.keys(STATUS_META) as ProjectStatus[];

const PAGE_SIZE = 5;

const ProjectQuotaPanel: React.FC = () => {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(ALL_STATUSES);
    setPage(1);
  };

  const filteredProjects = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses]
  );

  const totalPages = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, totalPages);

  const pageProjects = useMemo(
    () =>
      filteredProjects.slice(
        (currentPage - 1) * PAGE_SIZE,
        (currentPage - 1) * PAGE_SIZE + PAGE_SIZE
      ),
    [filteredProjects, currentPage]
  );

  return (
    <Card className="jx-p-lg">
      <Stack direction="column" gap="lg">
        <Stack direction="column" gap="sm">
          <Text variant="heading-sm" style={{ color: 'var(--jx-color-text-primary)' }}>
            Расход по проектам
          </Text>
          <ChipGroup aria-label="Фильтр по статусу">
            {ALL_STATUSES.map((status) => {
              const meta = STATUS_META[status];
              const isSelected = activeStatuses.includes(status);
              return (
                <Chip
                  key={status}
                  selected={isSelected}
                  removable={isSelected}
                  onRemove={() => toggleStatus(status)}
                  onClick={() => toggleStatus(status)}
                  tone={meta.tone}
                >
                  {meta.label}
                </Chip>
              );
            })}
          </ChipGroup>
        </Stack>

        {pageProjects.length === 0 ? (
          <EmptyState
            title="Нет проектов по выбранным фильтрам"
            description="Попробуйте изменить набор статусов или сбросьте фильтры."
            action={
              <Button variant="secondary" onClick={resetFilters}>
                Сбросить фильтры
              </Button>
            }
          />
        ) : (
          <>
            <Stack direction="column" gap="sm">
              {pageProjects.map((project) => {
                const meta = STATUS_META[project.status];
                return (
                  <Stack
                    key={project.id}
                    direction="row"
                    align="center"
                    justify="space-between"
                    gap="md"
                    className="jx-p-md jx-border-radius-md"
                    style={{
                      border: '1px solid var(--jx-color-border-default)',
                      backgroundColor: 'var(--jx-color-surface-secondary)',
                    }}
                  >
                    <Text variant="body-md" style={{ color: 'var(--jx-color-text-primary)' }}>
                      {project.name}
                    </Text>
                    <Stack direction="row" align="center" gap="md">
                      <CircularProgress
                        value={project.quotaPercent}
                        max={100}
                        size="sm"
                        label={`${project.quotaPercent}%`}
                        tone={meta.tone}
                      />
                      <Badge tone={meta.tone}>{meta.label}</Badge>
                    </Stack>
                  </Stack>
                );
              })}
            </Stack>

            <Pagination
              page={currentPage}
              totalPages={totalPages}
              onPageChange={setPage}
            />
          </>
        )}
      </Stack>
    </Card>
  );
};

export default ProjectQuotaPanel;

